head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.notiId;
scwin.strAcptNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        buttonSet.setSaveInfo(btn_save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_modify, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_delete, scwin.delete); // 삭제

        setInsertReadyStatus = "I";
        scwin.strAcptNo = $c.stf.getQuery(frame.srcUrl, "ACPT_NO");
        await scwin.read();

        // alert("dts_fileList.CountRow-->"+dts_fileList.CountRow);
        // 기존파일이 없으면
        if (dts_fileList.getRowCount() === 0) {
            buttonSet.setInsertStatus();
            scwin.setDataHeader();
        } else {
            buttonSet.setUpdateStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Read_OnLoadError
 * @description trs_Read 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Read_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.trs_Read_OnLoadError" });
    }
};

