        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일등록"));
        await $c.win.closePopup();
        // self.close();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.trs_Save_OnSuccess" });
