/**
 * @method
 * @name grd_userlist_OnDblClick
 * @description grd_userlist 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_userlist_OnDblClick = function(row, colid) {
    try {
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            $c.elw.fn_filedown(dts_fileList.getCellData(row, "SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.grd_userlist_OnDblClick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        if (scwin.notiId === "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            // dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
            file_name.setValue(inf_find.getValue());
        }
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「행삽입」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_lineadd_onclick = function() {
    try {
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            if (scwin.notiId === "input") {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
            } else {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                // dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
                file_name.setValue(inf_find.getValue());
            }
        } else {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup(); // self.close();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05239_FILE.btn_close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/ListedReceive.do",
        ref : "dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    let fileYn = "N";
    for (i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") !== "") {
            fileYn = "Y";
        }
    }
    if (fileYn === "N") {
        await $c.win.alert("첨부파일을 하나이상 등록해주세요");
        return;
    }
    let rtn = confirm('첨부파일을 등록 하시겠습니까?');
    if (rtn === 1) {
        // [확인] 버튼이 눌려졌을 경우
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ListedReceive.do",
            ref : "dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    dts_fileList.setBroadcast(false);
    for (i = 0; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") === "" && dts_fileList.getCellData(i, "filename") === "") {
            dts_fileList.removeRow(i);
        }
    }
    dts_fileList.setBroadcast(true, true);
    if (dts_fileList.getRowCount() === 0) {
        await $c.win.alert("첨부파일을 한개이상  입력해주세요.");
        return;
    }
    let rtn = confirm('첨부파일을 수정 하시겠습니까?');
    if (rtn === 1) {
        // [확인] 버튼이 눌려졌을 경우
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/ListedReceive.do",
            ref : "dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    let rtn = confirm('첨부파일을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_fileList.setBroadcast(false);
        for (i = 0; i <= dts_fileList.getRowCount(); i++) {
            dts_fileList.removeRow(i);
        }
        dts_fileList.setBroadcast(true, true);
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/ListedReceive.do",
            ref : "dts_fileList",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} attach_seq attach_seq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(attach_seq) {
    location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF05239_FILE.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + scwin.strAcptNo + "&attach_seq=" + attach_seq + "&gubun=32";
};

/**
 * @method
 * @name setDataHeader
 * @description set Data Header 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataHeader = function() {

    // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

};
